using AcxiomCRM.Data; using AcxiomCRM.Models; using Microsoft.AspNetCore.Authorization; using Microsoft.AspNetCore.Mvc; using Microsoft.EntityFrameworkCore;
namespace AcxiomCRM.Controllers; [Authorize] public class OpportunitiesController:Controller{private readonly ApplicationDbContext _db;public OpportunitiesController(ApplicationDbContext db)=>_db=db;public async Task<IActionResult>Index()=>View(await _db.Opportunities.OrderByDescending(x=>x.OpportunityId).ToListAsync());public IActionResult Create()=>View();[HttpPost]public async Task<IActionResult>Create(Opportunity o){if(o.Status=="Open"&&o.ExpectedCloseDate.Date<DateTime.Today)ModelState.AddModelError(nameof(o.ExpectedCloseDate),"Expected Close Date cannot be in the past.");if(ModelState.IsValid){_db.Opportunities.Add(o);await _db.SaveChangesAsync();_db.AuditLogs.Add(new AuditLog{Action="Create",EntityName="Opportunity",RecordId=o.OpportunityId.ToString(),UserId=User.Identity?.Name});await _db.SaveChangesAsync();return RedirectToAction(nameof(Index));}return View(o);}}
